function OverseaClubBossRewardNode:Awake()
    if self.BtnCheck then
        SetButtonAction(self.BtnCheck.gameObject,Bind(self,self.OnBtnCheckClick))
    end
end

function OverseaClubBossRewardNode:Refresh(data,isInRank,isNext,callback)
    self.callback = callback
    local isInRank = isInRank
    KTool.SetActive(self.Empty.gameObject,not isInRank)
    KTool.SetActive(self.ScrollView.gameObject, isInRank)

    if isInRank then
        local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
        rewardEnv:FreshBaseUI(data)
    else
        if not isNull(self.TextDesc) then
            local status = isNext and 2 or 1
            CfUtils.SetUISwitchText(self.TextDesc,status)
        end
    end

    if self.BtnCheck then
        KTool.SetActive(self.BtnCheck.gameObject,not isNext)
    end
end

function OverseaClubBossRewardNode:OnBtnCheckClick()
    if self.callback then
        self.callback()
    else
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIClubBossRankRewardDialog, parameters = { autoId = AutoIds.IdSetting6098} })    
    end
end

function OverseaClubBossRewardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaClubBossRewardNode